using System;
using Colossal.IO.AssetDatabase;

namespace BridgeBuilder.Bridges;

// Offline network-to-object descriptors retain the original texture CIDs and mips.
internal static class Draw02NativeMaterials
{
    // BEGIN generated native network sampling gate
    // Generated by EmitNetworkSampling.py. Only the shared fixed NetPiece graph
    // capability may call this gate; moving object renders keep their conversion.
    // Shader 581 preserves U and evaluates signed V using native network length.
    internal static bool IsNativeNetwork(string render, int mesh, string sourceCid)
    {
        string? expected = (render, mesh) switch
        {
            ("DrawBridge02BottomEdge350cm Mesh", 0) => "448cdebf6179c890a5db485ced29e061",
            ("DrawBridge02BottomEdge350cm_LOD1 Mesh", 0) => "7afdcc5d945bab37e86b2f076ea06ab1",
            ("DrawBridge02BottomEdge350cm_LOD2 Mesh", 0) => "02716b2feb419ec9313c34ae298a4a2b",
            ("DrawBridge02BottomEdgeNode350cm Mesh", 0) => "763e635445dd0cb62c4bd10f1efc35a1",
            ("DrawBridge02BottomEdgeNode350cm_LOD1 Mesh", 0) => "b34daec532867997c185d328653bd0bb",
            ("DrawBridge02BottomEdgeNode350cm_LOD2 Mesh", 0) => "1a7e0469c2e6fc4a4c5069c21bd1afe6",
            ("DrawBridge02BottomInner300cm Mesh", 0) => "5d98bd98700c73926bb2b3ff69c784e2",
            ("DrawBridge02BottomInner300cm_LOD1 Mesh", 0) => "9f31e9f71c97263c984303131decbfb0",
            ("DrawBridge02BottomInner300cm_LOD2 Mesh", 0) => "9b0ef24ab46511040acf280f549a3a73",
            ("DrawBridge02BottomInnerNode300cm Mesh", 0) => "4f700e65d6da0bd1ada6e8986ba5844f",
            ("DrawBridge02BottomInnerNode300cm_LOD1 Mesh", 0) => "af48c4b16775963b7d025f9f672722f1",
            ("DrawBridge02BottomInnerNode300cm_LOD2 Mesh", 0) => "55697a0c744a3cfa77056b9ff0f93646",
            ("DrawBridge02BottomIntersectionMiddle200cm Mesh", 0) => "dee7bfe689bf6752861f0f6f29a6c8e2",
            ("DrawBridge02BottomOuter300cm Mesh", 0) => "8ce855cf963887d8c227feb4c454f720",
            ("DrawBridge02BottomOuter300cm_LOD1 Mesh", 0) => "34c9949500ff04bf4852f3c3d43d52f0",
            ("DrawBridge02BottomOuter300cm_LOD2 Mesh", 0) => "2df8eba06013ff484033c13b88132e60",
            ("DrawBridge02BottomOuterNode300cm Mesh", 0) => "e038420b81ed5bb1f99fb41f30a4553c",
            ("DrawBridge02BottomOuterNode300cm_LOD1 Mesh", 0) => "bca14529bb6eb82a20ba60fb1eb3e9cf",
            ("DrawBridge02BottomOuterNode300cm_LOD2 Mesh", 0) => "1475f619dbbb4437aca2c49623c0a1e1",
            _ => null
        };
        return expected != null && sourceCid == expected;
    }
    // END generated native network sampling gate

    internal static string? ObjectDescriptor(string sourceCid) => sourceCid switch
    {
        "55697a0c744a3cfa77056b9ff0f93646" or "9b0ef24ab46511040acf280f549a3a73"
            => "e7e3a33d1499167c8c385ebfb70af78b",
        "5d98bd98700c73926bb2b3ff69c784e2" or "9f31e9f71c97263c984303131decbfb0"
            or "af48c4b16775963b7d025f9f672722f1" or "dee7bfe689bf6752861f0f6f29a6c8e2"
            => "1d6c92d008a952b1db4e1cc6cf7a1160",
        _ => null
    };

    // The shared caller owns style-local loading and asset lifetime. These
    // descriptors require original source-atlas UVs rather than baked-page UVs.
    internal static SurfaceAsset Resolve(SurfaceAsset original, Func<string, SurfaceAsset> load)
    {
        var cid = ObjectDescriptor(original.id.guid.ToString());
        if (cid == null) return original;
        original.LoadHeader();
        if (!original.isBuiltin || original.materialTemplateHash is not 17)
            throw new InvalidOperationException("Draw02 native network surface identity or template differs: " + original.id);
        var converted = load(cid);
        converted.LoadHeader();
        if (converted.id.guid.ToString() != cid || converted.materialTemplateHash is not 0 || converted.isVTMaterial)
            throw new InvalidOperationException("Draw02 native object descriptor differs: " + cid);
        return converted;
    }
}
